import {hintsFor} from './hints.js';
import {documentationSources,sourceFolders} from './sources.js';
import {solutionOptions} from './solutions.js';
import {SharedReports} from './reports.js';
import {packageOptions,enabledExercises,normalizePackages} from './packages.js';
import {examSheet} from './exam-sheet.js';
import {Account} from './account.js';
import {topics,exercises as courseExercises,makeVariant,kindLabels} from './course.js';
import {olaExercises,olaYears,normalizeOlaYears} from './ola-exercises.js';
import {KEY,emptyProgress,loadProgress,validateProgress,summary,dayKey,gradeText,selectExam,skipExamQuestion,examScore,prepareExerciseDraft} from './progress.js';
import {runCode,resetEngine} from './engine.js';

const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>({home:'◫',tasks:'⌘',ola:'∑',exam:'◷',stats:'↗',reference:'≡',settings:'⚙'}[name]||'→');
let storage;try{storage=localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Storage unavailable');}};}
const allExercises=[...courseExercises,...olaExercises];
let progress=loadProgress(storage);let exercises;let page='home',current=null,filter='all',level='all',kind='all',search='',session=null,examMode=false,feedback=null,busy=false,runSequence=0,lastResult=null;
let runtimeStatus='R starter ved første kørsel';let toastTimer;
let account;
const sharedReports=new SharedReports({onChange:()=>{if(page==='reports'&&!current)render();}});
function save(){try{if(account)account.save(progress);else storage.setItem(KEY,JSON.stringify(progress));}catch{toast('Browseren kan ikke gemme. Eksportér dine resultater fra Indstillinger.');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function coreActiveExercises(){return enabledExercises(courseExercises,normalizePackages(progress.enabledPackages));}
function activeExercises(){return [...coreActiveExercises(),...olaExercises.filter(x=>normalizeOlaYears(progress.enabledOlaYears).includes(x.olaYear))];}
function stats(){return summary(progress,exercises);}
function dateText(at){return new Date(at).toLocaleDateString('da-DK',{day:'numeric',month:'short'});}
function duration(n){return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;}
function currentDraftKey(){return examMode?`${progress.activeExam?.id}:${current.id}`:current.id;}
function rememberDraft(){const el=$('#answer');if(el&&current){progress.drafts[currentDraftKey()]=el.value;save();}}
function navigate(target){rememberDraft();runSequence++;page=target;current=null;examMode=false;feedback=null;busy=false;render();if(target==='reports')sharedReports.refresh(progress.reports);window.scrollTo(0,0);}
function topicOf(ex){return topics.find(t=>t.id===ex.topic);}

function packageMenu(){const selected=normalizePackages(progress.enabledPackages);const count=selected.filter(p=>p!=='baseR'&&p!=='__baseR_off__').length;return `<section class="package-chooser" aria-labelledby="package-title"><div class="package-chooser-heading"><div><strong id="package-title">Vælg opgavepakker</strong><p>Base R er altid med i kodelabbet. Slå de pakker til, du vil øve.</p></div><span>${selected.includes('baseR')?'Base R tilvalgt':'Base R fravalgt'} · ${count} pakker</span></div><div class="package-options"><label class="package-option"><input type="checkbox" data-package="baseR" ${selected.includes('baseR')?'checked':''} ${busy||progress.activeExam?'disabled':''}><span><strong>Base R</strong><small>Grundlaget · inklusive str()</small></span></label>${packageOptions.map(p=>`<label class="package-option"><input type="checkbox" data-package="${p.id}" ${selected.includes(p.id)?'checked':''} ${busy||progress.activeExam?'disabled':''}><span><strong>${p.id}</strong><small>${p.description}</small></span></label>`).join('')}</div>${!selected.includes('baseR')?'<p class="package-warning" role="alert"><strong>Advarsel:</strong> Base R-opgaver er skjult. Opgaver fra de øvrige valgte pakker vises stadig.</p>':''}<p class="package-note">Pakkevalget styrer kun, hvilke ekstra opgaver der vises. Alle fem pakker kan bruges i alle kodeopgaver. Opgaverne bygger på undervisningsmaterialet, eksklusive OLA-opgaver.</p>${progress.activeExam?'<p class="package-note">Afslut den aktive prøve for at ændre pakker.</p>':''}</section>`;}
function bindPackages(){document.querySelectorAll('[data-package]').forEach(input=>input.onchange=()=>{if(busy||progress.activeExam)return;if(input.dataset.package==='baseR'&&!input.checked&&!window.confirm('Advarsel: Base R-opgaver bliver skjult fra opgaveoversigten. Du kan slå Base R til igen når som helst. Vil du fortsætte?')){input.checked=true;return;}rememberDraft();const selected=new Set(normalizePackages(progress.enabledPackages));if(input.checked){selected.add(input.dataset.package);if(input.dataset.package==='baseR')selected.delete('__baseR_off__');}else{selected.delete(input.dataset.package);if(input.dataset.package==='baseR')selected.add('__baseR_off__');}progress.enabledPackages=[...selected];save();runSequence++;current=null;session=null;examMode=false;feedback=null;render();});}

function pill(ex){return `<span class="tag">${(ex.packages||[]).join(" + ")||kindLabels[ex.kind]}</span><span class="level level-${ex.level}">${['','Grundlag','Øvet','Udfordring'][ex.level]}</span>`;}
function button(text,action,cls='primary',attrs=''){return `<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
function render(){
 exercises=activeExercises();
 const s=stats();const nav=[['home','Overblik'],['tasks','Opgavebibliotek'],['ola','OLA-træning'],['exam','Eksamenstræning'],['stats','Din udvikling'],['reports','Fejlrapporter']];
 $('#app').innerHTML=`<aside class="sidebar"><a href="#" class="brand" data-nav="home"><span class="brandmark">R<span>_</span></span><span>R Lab<span class="brand-sub">DIT PERSONLIGE KODELAB</span></span></a><div class="nav-label">DIT WORKSPACE</div><nav aria-label="Hovedmenu">${nav.map(([id,label])=>`<button class="nav-item ${page===id?'active':''}" data-nav="${id}" ${page===id?'aria-current="page"':''}><span class="nav-icon">${icon(id)}</span>${label}${id==='tasks'?`<span class="nav-count">${coreActiveExercises().length}</span>`:id==='ola'?`<span class="nav-count">${olaExercises.filter(x=>normalizeOlaYears(progress.enabledOlaYears).includes(x.olaYear)).length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-card"><span class="tiny lime">LIDT HVER DAG</span><strong>Små skridt.<br>Stærkere i R.</strong><p>Dit daglige mål</p><div class="goal-line"><span>${s.today} / ${progress.dailyGoal} opgaver</span><span>${Math.min(100,Math.round(s.today/progress.dailyGoal*100))}%</span></div><div class="track"><i style="width:${Math.min(100,s.today/progress.dailyGoal*100)}%"></i></div></div><nav class="bottom-nav" aria-label="Hjælp"><button class="nav-item ${page==='sources'?'active':''}" data-nav="sources"><span class="nav-icon">▤</span>Kildeliste</button><button class="nav-item ${page==='reference'?'active':''}" data-nav="reference"><span class="nav-icon">≡</span>R-håndbogen</button><button class="nav-item ${page==='settings'?'active':''}" data-nav="settings"><span class="nav-icon">⚙</span>Indstillinger</button></nav>${account.badge()}</aside><div class="main-shell"><header class="topbar"><div><span class="breadcrumb">Mit workspace</span><span class="slash">/</span><strong>${current?'Træningsrum':{home:'Overblik',tasks:'Opgavebibliotek',ola:'OLA-træning',exam:'Eksamenstræning',stats:'Din udvikling',reference:'R-håndbogen',settings:'Indstillinger',sources:'Kildeliste',reports:'Fejlrapporter',profile:'Min profil'}[page]}</strong></div><div class="top-right"><span class="streak">♧ <strong>${s.streak}</strong> dages streak</span></div></header><main id="main" tabindex="-1">${account.user&&account.status==='loading'?'<section class="card"><h2>Henter din profil…</h2><p>Dine resultater er på vej.</p></section>':current?exerciseView():{home:homeView,tasks:tasksView,ola:olaView,exam:examView,stats:statsView,reference:referenceView,sources:sourcesView,settings:settingsView,reports:reportsView,profile:()=>account.view()}[page]()}</main><footer>Bygget til undervisningens pensum. Ét problem, én løsning, ét skridt videre.<span>R LAB <span class="footer-dot">•</span> BASE R</span></footer></div>`;
 bind();if(current){const a=$('#answer');if(a)a.value=progress.drafts[currentDraftKey()]??(current.kind==='output'?'':current.starter)??'';drawResult();setBusy(busy);}
}
function homeView(){const s=stats();const pool=coreActiveExercises();const next=pool.find(x=>!s.solved.has(x.id))||pool[0];return `<section class="page-heading"><div><p class="eyebrow">DIN PERSONLIGE TRÆNINGSBANE</p><h1>Klar til at tænke i R?</h1><p>AI-genererede og udvalgte øvelser – baseret på undervisningens opgaver og materiale.</p></div><span class="date-label">${new Date().toLocaleDateString('da-DK',{day:'numeric',month:'long',year:'numeric'})}</span></section><section class="hero"><div class="hero-copy"><span class="hero-badge"><i></i> LÆR VED AT GØRE</span><h2>Mindre tvivl.<br>Mere <span>kode.</span></h2><p>Træn med opgaver fra undervisningsmaterialet. Skriv R, få feedback, og se dig selv blive bedre.</p><div class="hero-actions">${button('Fortsæt din træning <span>↗</span>','open','lime-button',`data-id="${next.id}"`)}<span class="hero-note">${exercises.length} opgaver · dit tempo</span></div></div><div class="hero-code" aria-label="Eksempel på R-kode"><div class="code-window-bar"><span><i></i><i></i><i></i></span><span>din_næste_sejr.R</span><span>R</span></div><div class="code-lines"><span class="comment"># Et lille skridt mod forståelse</span><br><span class="code-blue">biler</span> <span class="code-lime">&lt;-</span> mtcars<br><br><span class="comment"># Find det, der betyder noget</span><br>biler[biler$mpg <span class="code-lime">&gt;</span> <span class="code-orange">20</span>, ]<br><br><span class="comment"># Du er allerede i gang.</span><br><span class="terminal-cursor">▌</span></div><div class="code-bottom"><span><i class="online-dot"></i> Base R · klar til at lære</span><span>UTF-8</span></div></div><div class="hero-orbit" aria-hidden="true"></div></section>${packageMenu()}<section class="metrics">${metric('Opgaver løst',`${s.solved.size}<small> / ${exercises.length}</small>`,'Unikke opgaver uden vist facit','✓')}${metric('Korrekte svar',s.attempts?`${s.accuracy}<small>%</small>`:'—',s.attempts?`${s.attempts} træningsforsøg i alt`:'Din statistik begynder ved første svar','◎')}${metric('Træningstid',`${s.minutes}<small> min</small>`,'Aktiv tid på besvarede opgaver','◷')}${metric('Dagens fremskridt',`${s.today}<small> / ${progress.dailyGoal}</small>`,s.today>=progress.dailyGoal?'Dit dagsmål er nået!':'Lidt træning gør en forskel','↗')}</section><section class="section-title"><div><p class="eyebrow">BYG DINE FÆRDIGHEDER</p><h2>Hvad vil du træne?</h2></div><button class="text-button" data-nav="tasks">Alle opgaver <span>→</span></button></section><section class="topic-grid">${topics.map((t,i)=>topicCard(t,i,s)).join('')}</section><section class="bottom-grid"><div class="exam-callout"><span class="exam-symbol">◷</span><div><span class="eyebrow">PRØV DIG SELV AF</span><h3>Et lille eksamensøjeblik</h3><p>10 blandede opgaver. 20 minutter. Feedback, når du er færdig.</p></div><button class="secondary" data-nav="exam">Start en prøve →</button></div><div class="source-note"><span class="tiny">FRA UNDERVISNINGSMATERIALET</span><strong>Velkendte emner. Nye udfordringer.</strong><p>Fra mtcars og bilpriser til terningekast og regression. Tilpasset base R.</p></div></section>`;}
function metric(label,value,note,symbol){return `<article class="metric"><div>${label}<span>${symbol}</span></div><strong>${value}</strong><small>${note}</small></article>`;}
function topicCard(t,i,s){const a=s.topics[t.id];return `<button class="topic-card" data-topic="${t.id}"><div class="topic-top"><span class="topic-icon color-${i}">${t.icon}</span><span class="topic-number">0${i+1} <span>↗</span></span></div><h3>${t.name}</h3><p>${t.description}</p><div class="topic-progress"><span>${a.solved} af ${a.total} løst</span><span>${Math.round(a.solved/a.total*100)}%</span></div><div class="track"><i style="width:${a.solved/a.total*100}%"></i></div></button>`;}

function examChecklist(){const solved=stats().solved;const items=examSheet.flatMap(g=>g.items);const complete=items.filter(([, ,ids])=>ids.every(id=>solved.has(id))).length;return `<details class="card exam-sheet"><summary><span><strong>Alle spørgsmål fra undervisningens eksamensfil</strong><small>Eksamenstræningsopgaver - Svar.R · opgave 1–6, inklusive ekstra udfordring</small></span><span>${complete} / ${items.length} gennemført · Åbn listen</span></summary><p>Hvert spørgsmål er koblet til en eller flere øvelser. Facit er rettet, hvor den oprindelige fil havde fejl. Alle løsninger bruger base R fra undervisningsmaterialet uden OLA.</p>${examSheet.map(group=>`<section><h3>${group.title}</h3>${group.items.map(([number,label,ids])=>`<div class="sheet-row"><div><strong>${number}</strong> ${label}</div><div>${ids.map(id=>{const ex=exercises.find(e=>e.id===id);return `<button class="secondary" data-action="open" data-id="${id}">${solved.has(id)?'✓ ':''}${ids.length>1?esc(ex.title):'Træn opgaven →'}</button>`;}).join('')}</div></div>`).join('')}</section>`).join('')}</details>`;}

function tasksView(){const s=stats();const list=exercises.filter(x=>!x.olaYear&&(filter==='all'||x.topic===filter)&&(level==='all'||x.level===+level)&&(kind==='all'||x.kind===kind)&&`${x.title} ${x.prompt}`.toLowerCase().includes(search.toLowerCase()));return `<section class="page-heading"><div><p class="eyebrow">ØVELSE GØR FORSKELLEN</p><h1>Dit opgavebibliotek</h1><p>Vælg en færdighed. Skriv kode. Forstå hvorfor det virker.</p></div>${button('↻ Generér ny variant','variant','secondary')}</section>${examChecklist()}<div class="filter-tabs" role="group" aria-label="Filtrér emner"><button class="${filter==='all'?'selected':''}" data-filter="all">Alle emner</button>${topics.map(t=>`<button class="${filter===t.id?'selected':''}" data-filter="${t.id}">${t.name}</button>`).join('')}</div><div class="filters"><label class="search"><span>⌕</span><input id="search" placeholder="Find en opgave…" value="${esc(search)}" aria-label="Søg i opgaver"></label><label><span class="sr-only">Niveau</span><select id="level"><option value="all">Alle niveauer</option>${[1,2,3].map(n=>`<option value="${n}" ${level==n?'selected':''}>${['','Grundlag','Øvet','Udfordring'][n]}</option>`).join('')}</select></label><label><span class="sr-only">Opgavetype</span><select id="kind"><option value="all">Alle opgavetyper</option>${Object.entries(kindLabels).map(([id,name])=>`<option value="${id}" ${kind===id?'selected':''}>${name}</option>`).join('')}</select></label><span class="muted">${list.length} opgaver</span></div><div class="exercise-list">${list.map(x=>`<button class="exercise-row" data-action="open" data-id="${x.id}"><span class="exercise-status ${s.solved.has(x.id)?'done':''}">${s.solved.has(x.id)?'✓':topicOf(x).icon}</span><span class="exercise-name"><strong>${x.title}</strong><small>${topicOf(x).name}</small></span><span class="row-tags">${pill(x)}</span><span class="arrow">→</span></button>`).join('')||'<div class="empty-state"><h3>Ingen opgaver matcher</h3><p>Prøv et andet søgeord eller et andet filter.</p></div>'}</div>`;}
function openExercise(id,variant=null,isExam=false){rememberDraft();runSequence++;current=variant||allExercises.find(x=>x.id===id);if(!current)return;page=isExam?'exam':current.olaYear?'ola':'tasks';examMode=isExam;feedback=null;lastResult=null;busy=false;session={start:Date.now(),seconds:0,hinted:false,revealed:false,choice:null,lastSubmitted:null};const cleared=prepareExerciseDraft(progress,currentDraftKey(),current.id,!['choice','output'].includes(current.kind));save();if(current.kind==='choice'){const saved=progress.drafts[currentDraftKey()];if(saved!==undefined)session.choice=Number(saved);}render();window.scrollTo(0,0);if(cleared)toast('Ny start uden facit. Dit tidligere svar med facit er fjernet fra kodefeltet.');}
function exerciseView(){const ex=current;const e=progress.activeExam;const isText=['choice','output'].includes(ex.kind);const exercisePool=ex.olaYear?exercises.filter(x=>x.olaYear===ex.olaYear):coreActiveExercises();const index=exercisePool.findIndex(x=>x.id===ex.id);return `<div class="workspace-heading"><button class="text-button" data-nav="${examMode?'exam':current.olaYear?'ola':'tasks'}">← ${examMode?'Til prøveoversigt':current.olaYear?'Til OLA-opgaver':'Til opgaver'}</button>${examMode?`<span class="exam-timer" id="exam-timer">${examTime()}</span><span>Opgave ${e.index+1} af ${e.ids.length}</span>`:`<span class="muted">${index>=0?`Opgave ${index+1} / ${exercises.length}`:'Ny træningsvariant'}</span>`}</div><div class="workspace"><section class="problem-panel"><div class="problem-label">${topicOf(ex)?.icon||'R'} ${topicOf(ex)?.name||'Træning'}</div><div class="tags">${pill(ex)}</div><h1>${ex.title}</h1><p class="problem-prompt">${esc(ex.prompt)}</p>${ex.setup?`<div class="field-title">${isText?'Læs koden':'Klargjort til dig'}</div><pre class="setup-code"><code>${esc(ex.setup)}</code></pre>${!isText?`<p class="small-note">Koden ovenfor køres automatisk før dit svar. Dataene findes allerede; du skal ikke oprette dem igen.</p>${button('Vis klargjorte data','preview-data','secondary')}`:''}`:''}<div class="instructions"><span>ⓘ</span><p>${isText?'Besvar opgaven i feltet til højre.':ex.id.startsWith('gg-')?'Skriv plotkoden, og lad figuren være dit sidste udtryk. Vi tester data, akser, grupper og diagramtype.':ex.check?'Opret det objekt eller den funktion, opgaven beder om. Vi tester resultatet. Store og små bogstaver i objektnavne er ligegyldige her.':'Lad resultatet være dit sidste udtryk. Du må gerne bruge flere linjer og mellemregninger.'}</p></div><div class="help-actions">${button('Der er en fejl','report','text-button')}${button('Spring over →','skip','secondary')}</div>${reportForm()}${!examMode?`<div class="help-actions">${button('◇ Få et hint','hint','secondary')}${button('Se løsningsforslag','solution','text-button')}</div><div id="help-area">${session.hinted?`<div class="hint-box" id="contextual-hints">${hintContent(ex,progress.drafts[currentDraftKey()]||'')}</div>`:''}${session.revealed?`<div class="hint-box"><strong>Løsningsforslag</strong><p>Her er forskellige korrekte måder at løse opgaven på. Pakker vises, hvor de er relevante. Andre korrekte løsninger kan også bruges.</p>${solutionOptions(ex).map(s=>`<section class="solution-option"><h4>${esc(s.label)}</h4><pre>${esc(s.code)}</pre>${s.note?`<p>${esc(s.note)}</p>`:''}</section>`).join('')}<p>${esc(ex.explanation)}</p><small>Forsøg efter vist facit tæller ikke som selvstændigt løst.</small></div>`:''}</div>`:'<div class="hint-box"><strong>Prøvetilstand</strong><p>Hints og facit vises efter prøven. Aflevering låser dit svar og går videre.</p></div>'}<details class="source-details"><summary>Om denne opgave</summary><p>Tilpasset fra <strong>${esc(ex.source)}</strong>.</p><p>Opgaver og løsningsforslag følger undervisningens R-funktioner og pakker. Data er indbygget eller syntetiske; eksterne API-kald er ikke nødvendige.</p><button class="text-button" data-nav="sources">Se hele kildelisten →</button></details></section><section class="answer-panel"><div class="editor-toolbar"><span><i class="file-dot"></i>${isText?'Dit svar':'besvarelse.R'}</span><span>${isText?'':`<span id="runtime-status">${runtimeStatus}</span>`}</span></div>${ex.kind==='choice'?`<fieldset class="choices"><legend class="sr-only">Vælg dit svar</legend>${ex.options.map((o,i)=>`<label><input type="radio" name="choice" value="${i}" ${session.choice===i?'checked':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></label>`).join('')}</fieldset>`:ex.kind==='output'?`<div class="output-answer"><label for="answer">Hvad bliver resultatet?</label><textarea id="answer" placeholder="Skriv fx 2 4 6" rows="4" spellcheck="false"></textarea><p>Du kan skrive værdier med mellemrum, kommaer eller som c(...).</p></div>`:`<div class="editor-wrap"><div class="line-numbers" id="line-numbers" aria-hidden="true">1</div><textarea id="answer" class="code-editor" aria-label="Skriv din R-kode" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" wrap="off"></textarea></div><div class="editor-shortcuts"><span>R · UTF-8</span><span>Alt/Option + - indsætter &lt;- · = er også tildeling</span><span>Ctrl/⌘ + Shift + M indsætter |&gt;</span><span>Ctrl / ⌘ + Enter for at tjekke</span></div>`}<div class="editor-actions">${!isText?button('▷ Kør kode','run','secondary'):''}${button(examMode?'Aflevér & fortsæt →':'Tjek mit svar →','submit','primary')} ${!isText?button('Nulstil kode','reset-code','text-button'):''}<span id="busy-label"></span></div><div id="feedback" aria-live="polite">${feedbackView()}</div><section class="console-panel"><div class="console-heading"><span>⌁ ${isText?'Feedback':'Konsol & figurer'}</span>${!isText?button('Genstart R','restart','text-button'):''}</div><pre id="console-output">${esc(lastResult?.output||(isText?'Dit svar bliver vurderet, når du afleverer.':'Kør din kode for at se output her.\nHver kørsel starter med opgavens oprindelige data.'))}</pre><div id="plots"></div></section>${!examMode?`<div class="next-row"><button class="text-button" data-action="variant">↻ Prøv en ny variant</button>${button('Næste opgave →','next','secondary')}</div>`:''}</section></div>`;}
function feedbackView(){if(!feedback)return '';return `<div class="feedback ${feedback.type}"><strong>${feedback.title}</strong><p>${esc(feedback.message)}</p></div>`;}
function updateFeedback(){if($('#feedback'))$('#feedback').innerHTML=feedbackView();}
function drawResult(){if(!lastResult?.images)return;const holder=$('#plots');if(!holder)return;holder.replaceChildren();lastResult.images.forEach(img=>{const canvas=document.createElement('canvas');canvas.width=img.width;canvas.height=img.height;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Figur fra din R-kode');canvas.getContext('2d').drawImage(img,0,0);holder.append(canvas);});}
function updateLines(){const a=$('#answer'),lines=$('#line-numbers');if(a&&lines){lines.textContent=Array.from({length:a.value.split('\n').length},(_,i)=>i+1).join('\n');lines.scrollTop=a.scrollTop;}}
function setBusy(value){busy=value;document.querySelectorAll('[data-action="submit"],[data-action="run"],[data-action="reset-code"],[data-action="skip"],[data-action="report"],[data-action="preview-data"]').forEach(b=>b.disabled=value);if($('#busy-label'))$('#busy-label').textContent=value?'Arbejder…':'';const stop=$('.console-panel [data-action="restart"]');if(stop)stop.textContent=value?'Stop indlæsning / kørsel':'Genstart R';}
async function evaluate(submit){
 if(!current||busy)return;if(examMode&&Date.now()>=progress.activeExam.endsAt){finishExam();return;}
 rememberDraft();const ex=current;const choice=$('input[name="choice"]:checked');const code=$('#answer')?.value||'';const isText=['choice','output'].includes(ex.kind);
 if(!isText&&!code.split(/\r?\n/).some(line=>line.trim()&&!line.trimStart().startsWith('#'))){toast('Skriv din egen løsning under kommentarerne først.');return;}
 if((ex.kind==='choice'&&!choice)||(ex.kind!=='choice'&&!code.trim())){toast('Skriv eller vælg et svar først.');return;}
 const seq=++runSequence;setBusy(true);feedback=null;updateFeedback();let correct=false;let error=null;
 try{
  if(isText)correct=gradeText(ex,ex.kind==='choice'?choice.value:code);
  else {lastResult=await runCode(ex,code,{grade:submit,status:msg=>{if(seq!==runSequence)return;runtimeStatus=msg;if($('#runtime-status'))$('#runtime-status').textContent=msg;}});correct=lastResult.correct;if(seq!==runSequence)return;$('#console-output').textContent=lastResult.output;drawResult();}
 }catch(e){error=e;}
 if(seq!==runSequence)return;
 if(examMode&&Date.now()>=progress.activeExam.endsAt){setBusy(false);finishExam();return;}
 setBusy(false);
 if(error){feedback={type:'error',title:'Koden kunne ikke køres',message:error.message};updateFeedback();return;}
 if(!submit){feedback={type:'neutral',title:'Koden er kørt',message:'Se resultatet i konsollen. Tryk “Tjek mit svar” for at få din løsning vurderet.'};updateFeedback();return;}
 const attempt={id:crypto.randomUUID(),exerciseId:ex.id,topic:ex.topic,correct,at:new Date().toISOString(),seconds:session.seconds,hinted:session.hinted,revealed:session.revealed,examId:examMode?progress.activeExam.id:null};session.seconds=0;
 progress.attempts.push(attempt);
 if(examMode){const e=progress.activeExam;e.answers[ex.id]={correct,answer:ex.kind==='choice'?ex.options[+choice.value]:code};e.index++;save();if(e.index>=e.ids.length){finishExam();return;}openExercise(e.ids[e.index],null,true);return;}
 save();feedback={type:correct?'success':'error',title:correct?'Godt arbejde. Den sidder!':'Ikke helt endnu — prøv igen',message:correct?(session.revealed?'Korrekt med hjælp fra facit. Prøv opgaven igen senere uden hjælp.':ex.explanation||'Dit resultat matcher opgaven. Du behøver ikke skrive præcis som facit.'):'Koden kører, men resultatet matcher ikke opgaven. Tjek værdier, kolonner og grænser. Rækkefølge tæller kun, når opgaven kræver det. Et hint kan hjælpe dig videre.'};render();
}
function hintContent(ex,code){return `<strong>Et lille skub</strong>${hintsFor(ex,code).map(hint=>`<section class="hint-method"><h4>${esc(hint.label)}</h4><p>${esc(hint.text)}</p></section>`).join('')}`;}
function updateHints(){const holder=$('#contextual-hints');if(holder&&current&&session.hinted&&!examMode)holder.innerHTML=hintContent(current,$('#answer')?.value||'');}
function reportForm(){
 if(!session.reportOpen)return '';
 return `<form id="report-form" class="hint-box report-form"><label for="report-description"><strong>Hvad er der galt?</strong></label><p>Beskriv fx en uklar opgave eller et korrekt svar, der bliver afvist. Forklaringen, opgaven, din kode og den viste feedback bliver synlige for alle i den fælles rapportliste.</p><textarea id="report-description" rows="4" maxlength="5000" required placeholder="Beskriv fejlen…">${esc(session.reportDraft||'')}</textarea><div class="button-row"><button class="primary" type="submit">Gem fejlrapport</button>${button('Annullér','cancel-report','text-button','type="button"')}</div></form>`;
}
async function submitReport(){
 if(!current||busy)return;
 const description=$('#report-description').value.trim();if(!description){$('#report-description').focus();return;}
 rememberDraft();progress.reports.push({id:crypto.randomUUID(),exerciseId:current.id,title:current.title,prompt:current.prompt,description,code:$('#answer')?.value||(session.choice!==null?current.options?.[session.choice]||'':''),feedback:feedback?.message||lastResult?.output||'',at:new Date().toISOString(),status:'open'});
 save();const report=progress.reports.at(-1);session.reportOpen=false;session.reportDraft='';render();try{await sharedReports.publish(report);toast('Fejlrapporten er gemt i den fælles liste og kan ses af alle.');}catch(error){toast('Forklaringen er gemt lokalt. '+error.message);}
}
function reportsView(){
 const reports=[...new Map([...progress.reports,...sharedReports.reports].map(r=>[r.id,r])).values()].sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));
 return `<section class="page-heading"><div><p class="eyebrow">HJÆLP MED AT FORBEDRE OPGAVERNE</p><h1>Fejlrapporter</h1><p>Fælles liste for alle besøgende, med og uden login. Alle kan oprette rapporter, markere dem som løst og genåbne dem.</p></div>${button('Opdatér listen','refresh-reports','secondary')}</section><p role="status">${sharedReports.loading?'Henter fælles rapporter…':esc(sharedReports.error)}</p><div class="review-list">${reports.map(r=>`<details class="review-item"><summary><span>${r.status==='resolved'?'✓':'⚑'}</span>${esc(r.title)}<span>${r.status==='resolved'?'Løst':'Åben'} · ${dateText(r.at)}</span></summary><p>${esc(r.description)}</p><p class="muted">${esc(r.prompt||'')} · ${esc(r.exerciseId)}</p><div class="review-columns"><div><strong>Indsendt kode / svar</strong><pre>${esc(r.code||'Intet svar')}</pre></div><div><strong>Feedback ved rapporteringen</strong><pre>${esc(r.feedback||'Ingen feedback endnu')}</pre></div></div>${button(r.status==='resolved'?'Genåbn':'Markér som løst','report-status','secondary',`data-id="${esc(r.id)}"`)}</details>`).join('')||'<section class="card"><h3>Ingen fejlrapporter endnu</h3><p>Brug knappen “Der er en fejl” inde på en opgave, hvis du opdager et problem.</p></section>'}</div>`;
}
async function previewData(){
 if(!current||busy)return;
 const ex=current,seq=++runSequence;rememberDraft();setBusy(true);
 try{const result=await runCode(ex,'invisible(lapply(mget(ls()), print))',{grade:false,status:msg=>{if(seq!==runSequence)return;runtimeStatus=msg;if($('#runtime-status'))$('#runtime-status').textContent=msg;}});if(seq!==runSequence)return;lastResult=result;$('#console-output').textContent=result.output;drawResult();toast('De klargjorte data vises i konsollen under dit svar.');$('#console-output')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
 catch(error){if(seq===runSequence){feedback={type:'error',title:'Data kunne ikke vises',message:error.message};updateFeedback();}}
 finally{if(seq===runSequence)setBusy(false);}
}
function skipCurrent(){
 if(!current||busy)return;
 rememberDraft();
 if(examMode){const e=progress.activeExam;if(Date.now()>=e.endsAt){finishExam();return;}skipExamQuestion(e);if(e.index>=e.ids.length){finishExam();return;}save();openExercise(e.ids[e.index],null,true);}
 else {const i=exercises.findIndex(x=>x.id===current.id);openExercise(exercises[(i+1)%exercises.length].id);}
 toast('Opgaven er sprunget over uden straf. Dit udkast er gemt.');
}
function examTime(){const e=progress.activeExam;if(!e)return '';return duration(Math.max(0,Math.ceil((e.endsAt-Date.now())/1000)));}
function olaGroupedList(year,available){const items=available.filter(x=>x.olaYear===year);const tasks=[...new Set(items.map(x=>x.olaTask))].sort((a,b)=>Number(a)-Number(b));return `<section class="section-title ola-section-title"><h2>OLA ${year}</h2><span class="muted">${items.length} træningsøvelser</span></section>${tasks.map(task=>{const group=items.filter(x=>x.olaTask===task);const subtasks=[...new Set(group.map(x=>x.olaSubtask))].sort((a,b)=>a.localeCompare(b,'da',{numeric:true}));return `<details class="ola-task-group" open><summary>Opgave ${task}<span>${group.length} træningsøvelser</span></summary>${subtasks.map(subtask=>`<section class="ola-subtask"><h3>Opgave ${esc(subtask)}</h3><div class="exercise-list">${group.filter(x=>x.olaSubtask===subtask).map(x=>`<button class="exercise-row" data-action="open" data-id="${x.id}"><span class="exercise-status">${topicOf(x)?.icon||'R'}</span><span class="exercise-name"><strong>${esc(x.title)}</strong><small>${topicOf(x)?.name||'OLA-træning'} · Niveau ${x.level}</small></span><span class="row-tags"><span class="level level-${x.level}">${['','Grundlag','Øvet','Udfordring'][x.level]}</span></span><span class="arrow">→</span></button>`).join('')}</div></section>`).join('')}</details>`;}).join('')}`;}
function olaView(){const selected=normalizeOlaYears(progress.enabledOlaYears);const available=olaExercises.filter(x=>selected.includes(x.olaYear));return `<section class="page-heading"><div><p class="eyebrow">EKSTRA TRÆNING FRA OLA-MATERIALET</p><h1>OLA-træning</h1><p>Vælg de OLA-forløb, du vil øve. Opgaverne træner kodeidéerne med små lokale datasæt; OLA 1, 4 og 5 er gjort klar som tomme pladser.</p></div></section><div class="ola-years">${olaYears.map(y=>`<label class="ola-year-card ${y.available?'':'unavailable'}"><input type="checkbox" data-ola-year="${y.id}" ${selected.includes(y.id)?'checked':''} ${!y.available||progress.activeExam?'disabled':''}><span><strong>${y.label}</strong><small>${y.description}</small>${y.available?`<small>${olaExercises.filter(x=>x.olaYear===y.id).length} træningsopgaver</small>`:'<small>Kommer senere</small>'}</span></label>`).join('')}</div>${!selected.length?'<div class="card ola-empty"><h3>Vælg OLA 2 eller OLA 3 for at begynde</h3><p>OLA-opgaverne holdes adskilt fra det almindelige opgavebibliotek.</p></div>':selected.map(year=>olaGroupedList(year,available)).join('')}`;}

function examView(){const e=progress.activeExam;const latest=progress.exams.at(-1);return `<section class="page-heading"><div><p class="eyebrow">FRA ØVELSE TIL OVERBLIK</p><h1>Test dig selv</h1><p>En prøve på tværs af undervisningens pensum. Ingen hints undervejs.</p></div></section><div class="exam-layout"><section class="exam-intro"><span class="big-symbol">◷</span><h2>${e?'Din prøve er i gang':'Et roligt rum til en rigtig udfordring'}</h2><p>${e?'Du kan fortsætte, hvor du slap. Tiden løber også, mens du er væk.':'Find ud af, hvad du kan selv, og hvor din næste træningsindsats gør størst forskel.'}</p><div class="exam-facts"><div><strong>10</strong><span>blandede opgaver</span></div><div><strong>20</strong><span>minutter</span></div><div><strong>6</strong><span>emner</span></div></div>${e?`${button(`Fortsæt prøve · ${examTime()} tilbage →`,'resume-exam','primary')}${button('Afslut prøven nu','finish-exam','text-button')}`:button('Start eksamenstræning →','start-exam','primary')}<p class="small-note">Skriv kode, ret fejl og besvar teorispørgsmål. Resultaterne holdes adskilt fra din daglige træning.</p></section><section class="card exam-guide"><p class="eyebrow">SÅDAN FOREGÅR DET</p><h3>På dine egne ben</h3><ol><li><strong>Få 10 tilfældige opgaver</strong><p>Alle seks emner er repræsenteret.</p></li><li><strong>Afprøv og aflever</strong><p>Du kan køre din kode. Når du afleverer, låses svaret.</p></li><li><strong>Få en konkret opsamling</strong><p>Se score, dine svar og løsningsforslag efter prøven. Opgaver, du vælger at springe over, tæller ikke med i scoren. Andre ubesvarede opgaver tæller som forkerte.</p></li></ol></section></div>${latest?`<section class="section-title"><h2>Seneste prøve</h2><span class="muted">${dateText(latest.at)}</span></section><section class="exam-result card"><div class="result-score"><strong>${latest.score}<span> / ${latest.total}</span></strong><p>${latest.total?Math.round(latest.score/latest.total*100)+'% korrekte':'Ingen bedømte opgaver'}${latest.skipped?.length?' · '+latest.skipped.length+' sprunget over':''}</p></div><div><h3>${!latest.total?'Ingen opgaver blev bedømt':latest.score/latest.total>=.8?'Et stærkt fundament':latest.total&&latest.score/latest.total>=.5?'Du er godt på vej':'Nu ved du, hvor du kan sætte ind'}</h3><p>Brug gennemgangen til at vælge din næste øvelse.</p></div></section><div class="review-list">${(latest.ids||[]).map(id=>{const ex=allExercises.find(x=>x.id===id);if(!ex)return '';const a=latest.answers?.[id];return `<details class="review-item"><summary><span class="${latest.skipped?.includes(id)?'muted':a?.correct?'green':'red'}">${latest.skipped?.includes(id)?'↷':a?.correct?'✓':'○'}</span>${ex.title}<span>${latest.skipped?.includes(id)?'Sprunget over — uden straf':a?a.correct?'Korrekt':'Prøv igen':'Ikke besvaret'}</span></summary><p>${esc(ex.prompt)}</p><div class="review-columns"><div><strong>Dit svar</strong><pre>${esc(a?.answer||'Ikke besvaret')}</pre></div><div><strong>Løsningsforslag</strong><p>Her er forskellige korrekte måder at løse opgaven på. Pakker vises, hvor de er relevante. Andre korrekte løsninger kan også bruges.</p>${solutionOptions(ex).map(s=>`<section class="solution-option"><h4>${esc(s.label)}</h4><pre>${esc(s.code)}</pre></section>`).join('')}</div></div><p>${esc(ex.explanation)}</p><button class="secondary" data-action="open" data-id="${id}">Træn opgaven igen →</button></details>`;}).join('')}</div>`:''}`;}
function startExam(){if(progress.activeExam){resumeExam();return;}progress.activeExam={id:`exam-${crypto.randomUUID()}`,ids:selectExam(coreActiveExercises()),index:0,answers:{},endsAt:Date.now()+20*60*1000};save();resumeExam();}
function resumeExam(){const e=progress.activeExam;if(!e)return;if(Date.now()>=e.endsAt){finishExam();return;}if(!e.ids.every(id=>allExercises.some(x=>x.id===id))){toast('Prøven stammer fra en anden version. Start en ny prøve.');progress.activeExam=null;save();render();return;}openExercise(e.ids[e.index],null,true);}
function finishExam(){const e=progress.activeExam;if(!e)return;rememberDraft();progress.exams.push({...e,at:new Date().toISOString(),...examScore(e)});progress.activeExam=null;save();navigate('exam');toast('Din prøve er afsluttet. Se resultatet og gennemgå svarene.');}
function statsView(){const s=stats();const history=progress.attempts.filter(x=>!x.examId);const days=Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-13+i);const a=history.filter(x=>dayKey(x.at)===dayKey(d));return {date:d,total:a.length,correct:a.filter(x=>x.correct).length};});const max=Math.max(5,...days.map(x=>x.total));const weak=topics.filter(t=>s.topics[t.id].attempts>0).sort((a,b)=>s.topics[a.id].accuracy-s.topics[b.id].accuracy)[0];return `<section class="page-heading"><div><p class="eyebrow">SE HVAD DER RYKKER SIG</p><h1>Din udvikling</h1><p>Ærlige tal fra dine egne besvarelser. Ingen opdigtede fremskridt.</p></div>${button('↓ Eksportér resultater','export','secondary')}</section><section class="metrics">${metric('Korrekt i første forsøg',history.length?`${s.firstAccuracy}<small>%</small>`:'—','Første forsøg uden hint eller facit','◎')}${metric('Opgaver løst',s.solved.size,'Uden at se facit i samme forsøg','✓')}${metric('Aktiv træning',`${s.minutes}<small> min</small>`,'Tid med en åben opgave i fokus','◷')}${metric('Gennemførte prøver',progress.exams.length,'Eksamensresultater tælles separat','↗')}</section><section class="analytics-grid"><div class="card"><div class="section-title compact"><h3>Din aktivitet</h3><span class="muted">Seneste 14 dage</span></div><div class="chart" role="img" aria-label="Antal træningsforsøg pr. dag de seneste 14 dage">${days.map(d=>`<div class="chart-col"><span class="bar-value">${d.total||''}</span><div class="bar-space"><div class="chart-bar" style="height:${d.total/max*100}%" title="${dateText(d.date)}: ${d.total} forsøg, ${d.correct} korrekte"><i style="height:${d.total?d.correct/d.total*100:0}%"></i></div></div><span>${d.date.getDate()}</span></div>`).join('')}</div><div class="chart-legend"><span><i class="legend-correct"></i>Korrekte forsøg</span><span><i></i>Øvrige forsøg</span></div>${!history.length?'<p class="empty-inline">Her vokser din historik frem, når du besvarer opgaver.</p>':''}</div><div class="card recommendation"><span class="eyebrow">DIT NÆSTE GODE SKRIDT</span><span class="recommend-icon">↗</span><h3>${weak?weak.name:'Start med fundamentet'}</h3><p>${weak?`Du har ${s.topics[weak.id].accuracy}% korrekte svar i dette emne. Lidt ekstra træning her er et godt næste skridt.`:'Du har ingen træningsdata endnu. Begynd med vektorer og typer, og lær arbejdsformen at kende.'}</p><button class="primary" data-topic="${weak?.id||'vectors'}">Træn emnet →</button></div></section><section class="section-title"><h2>Færdigheder, emne for emne</h2></section><div class="skills-table card"><div class="table-head"><span>Emne</span><span>Løst</span><span>Korrekte svar</span><span>Forsøg</span></div>${topics.map(t=>{const x=s.topics[t.id];return `<div class="skill-row"><strong>${t.icon} ${t.name}</strong><span>${x.solved} / ${x.total}</span><span>${x.accuracy===null?'—':x.accuracy+'%'}<span class="mini-track"><i style="width:${x.accuracy||0}%"></i></span></span><span>${x.attempts}</span></div>`;}).join('')}</div><section class="section-title"><h2>Seneste besvarelser</h2><span class="muted">Træning · seneste 12</span></section><div class="card history">${history.slice(-12).reverse().map(a=>`<div><span class="${a.correct?'green':'red'}">${a.correct?'✓':'○'}</span><strong>${esc(allExercises.find(x=>x.id===a.exerciseId)?.title||'Genereret variant')}</strong><span>${a.revealed?'Med facit':a.hinted?'Med hint':'Uden hjælp'}</span><time>${dateText(a.at)}</time></div>`).join('')||'<p class="muted">Din første besvarelse starter historikken.</p>'}</div>`;}
function referenceView(){const entries=[['Vektorer','c(2, 4, 6)\nseq(1, 10, by = 2)\nrep(c(TRUE, FALSE), 3)\nx[x > 4]','Indekser starter ved 1. Logiske vektorer kan bruges som filtre.'],['Data frames','head(biler, 6)\ndim(biler)\nstr(biler)\nbiler[, c("mpg", "hp")]','data[rækker, kolonner]. Et tomt felt betyder alle rækker eller kolonner.'],['Filtrering','biler[biler$hp > 150, ]\nbiler[biler$cyl == 4 & biler$mpg > 20, ]\nbiler[biler$cyl %in% c(4, 8), ]','& betyder OG, | betyder ELLER. == sammenligner, <- tildeler.'],['Sortering','biler[order(biler$mpg), ]\nhead(biler[order(biler$hp, decreasing=TRUE), ], 5)','order() giver positioner, som sorterer hele rækker. sort() sorterer kun den vektor, du giver den.'],['Manglende data','is.na(x)\nsum(is.na(x))\nx[!is.na(x)]\nmean(x, na.rm = TRUE)','Sammenlign ikke med == NA. Brug is.na().'],['Statistik','mean(x)\nmedian(x)\nsd(x)\naggregate(mpg ~ cyl, data = biler, FUN = mean)\ntable(biler$cyl)','sd() er stikprøvens standardafvigelse. aggregate() beregner noget for hver gruppe.'],['Funktioner & løkker','omregn <- function(x) x * 2.54\ntotal <- 0\nfor (x in 1:5) total <- total + x\nsapply(list(1:3, 4:6), mean)','Foretræk vektoriserede beregninger, når de udtrykker opgaven klart.'],['Simulation & modeller','set.seed(42)\nsample(1:6, 100, replace = TRUE)\nreplicate(100, sum(sample(1:6, 2, TRUE)))\nmodel <- lm(mpg ~ wt, data = mtcars)\nsummary(model)$r.squared','Et seed gør simulationen reproducerbar. R² beskriver modellens forklaringsgrad i de data, den er tilpasset til.'],['Visualisering','plot(mtcars$wt, mtcars$mpg,\n     xlab = "Vægt", ylab = "MPG")\nhist(mtcars$mpg)\ntable(mtcars$cyl)','Prøv disse i kodeøvelsernes editor. Figurer vises under konsollen. Visuel kvalitet bedømmes ikke automatisk.']];return `<section class="page-heading"><div><p class="eyebrow">ET OPSLAG, IKKE ET FACIT</p><h1>R-håndbogen</h1><p>De vigtigste byggesten fra undervisningens pensum, samlet ét sted.</p></div></section><div class="reference-grid">${entries.map(([title,code,note])=>`<article class="card"><h3>${title}</h3><pre>${esc(code)}</pre><p>${note}</p></article>`).join('')}</div><section class="card material-note"><h3>Sådan er undervisningsmaterialet brugt</h3><p>27 R-filer uden OLA-mapper er gennemgået. OLA-mapper er udeladt på alle mappeniveauer. Øvelserne bygger på introduktion, pair programming, eksamenstræning, bildata, terningeforsøg og makroanalyse. API-, scraping- og pakkeafhængige forløb er omsat til selvstændige base R-øvelser med lokale data. De oprindelige filer og adgangsoplysninger er ikke offentliggjort.</p><p>Fejl i tidligere løsningsforsøg er rettet, blandt andet & versus |, str() versus structure(), præcis brug af > og >= samt 37 °C = 98.6 °F.</p></section>`;}
const redactedSourceFiles=new Set(["02-11-2026 Tavle undervisning.R","OpenSky/GetPlanes.R","OpenSky/util.R","util.r"]);
function sourcesView(){
 return `<section class="page-heading"><div><p class="eyebrow">MATERIALET BAG OPGAVERNE</p><h1>Kildeliste</h1><p>Et overblik over undervisningsmapperne og deres indhold. Fold en mappe ud, hvis du vil se filerne. OLA 2 og OLA 3 har hver sin mappe med opgavebeskrivelser.</p></div></section><section class="section-title"><h2>Undervisningsmapper</h2></section><div class="reference-grid source-grid">${sourceFolders.map(folder=>{
 const paths=new Set(folder.files.map(file=>file.path));
 const linked=allExercises.filter(ex=>ex.source===folder.path||ex.source.startsWith(folder.path+'/')||ex.source.split(' · ').some(path=>paths.has(path)));
 return `<article class="card"><h3>${esc(folder.name)}</h3><p>${esc(folder.description)}</p><p class="small-note">${folder.files.length} ${folder.files.length===1?'fil':'filer'}${linked.length?' · '+linked.length+' opgaver henviser til materialet':''}${!folder.path?' · placeret uden for mapperne':''}</p><details class="source-folder-files"><summary>Se ${folder.files.length===1?'filen':'filerne'} i ${folder.path?'mappen':'det fælles materiale'}</summary><ul>${folder.files.map(file=>`<li><strong>${esc(folder.path?file.path.slice(folder.path.length+1):file.path)}</strong><p>${esc(file.description)}</p><a href="/source-files/${esc(file.path.split('/').map(encodeURIComponent).join('/'))}" download="${esc(file.path.split('/').at(-1))}">Download ${esc(file.path.split('/').at(-1))}</a>${redactedSourceFiles.has(file.path)?'<p class="small-note">Loginoplysninger er erstattet med miljøvariabler.</p>':''}</li>`).join('')}</ul></details></article>`;
 }).join('')}</div><section class="section-title"><h2>Officiel dokumentation</h2></section><div class="reference-grid">${documentationSources.map(source=>`<article class="card"><h3><a href="${source.url}" target="_blank" rel="noopener noreferrer">${esc(source.name)} ↗</a></h3><p>${esc(source.description)}</p></article>`).join('')}</div>`;
}
function settingsView(){return `<section class="page-heading"><div><p class="eyebrow">GØR TRÆNINGEN TIL DIN</p><h1>Indstillinger</h1><p>Din træning og dine data, på dine præmisser.</p></div></section><div class="settings-grid"><section class="card"><h3>Dit daglige mål</h3><p>Vælg et realistisk antal unikke opgaver, du vil løse hver dag.</p><div class="goal-options">${[3,5,10].map(n=>`<button data-goal="${n}" class="${progress.dailyGoal===n?'selected':''}"><strong>${n}</strong><span>opgaver / dag</span></button>`).join('')}</div></section><section class="card"><h3>Dine resultater</h3><p>${account.user?'Fremskridt og kladder synkroniseres med din profil. Status ses under Min profil.':'Fremskridt gemmes i denne browser. Log ind via profilsiden for at gemme online.'} En eksport indeholder dine svar.</p><div class="button-row">${button('↓ Eksportér backup','export','primary')}<label class="secondary file-label">↑ Importér backup<input id="import" type="file" accept="application/json,.json" class="sr-only"></label></div><p class="small-note">Import erstatter din nuværende historik efter bekræftelse, også online når du er logget ind.</p></section><section class="card"><h3>Om R-motoren</h3><p>Din kode kører i browseren med WebR 0.6.0. Første kørsel henter R-motoren fra r-wasm.org og kan tage lidt tid. Der kræves internet ved indlæsning. Dine besvarelser sendes ikke til en bedømmelsesserver.</p><p>Hver kørsel får friske opgavedata. Lange kørsler afbrydes efter 15 sekunder. Dette er træning med synligt facit i kildekoden, ikke en sikret eksamensplatform.</p>${button('Genstart R-motor','restart','secondary')}</section><section class="card danger-zone"><h3>Start på en frisk</h3><p>Nulstil træningshistorik, eksamensresultater og kladder${account.user?' på din konto og online':' på denne enhed'}. Eksportér en backup først, hvis du vil gemme dem.</p>${button('Nulstil mine data','clear-data','danger')}</section></div>`;}
function bind(){
 bindPackages();
 document.querySelectorAll('[data-ola-year]').forEach(input=>input.onchange=()=>{const selected=new Set(normalizeOlaYears(progress.enabledOlaYears));if(input.checked)selected.add(input.dataset.olaYear);else selected.delete(input.dataset.olaYear);progress.enabledOlaYears=[...selected];save();exercises=activeExercises();render();});
 account.bind();
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=e=>{e.preventDefault();navigate(b.dataset.nav);});
 document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{filter=b.dataset.topic;search='';level='all';kind='all';navigate('tasks');});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});
 document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{progress.dailyGoal=+b.dataset.goal;save();render();});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action,b.dataset.id));
 if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};
 for(const id of ['level','kind'])if($('#'+id))$('#'+id).onchange=e=>{if(id==='level')level=e.target.value;else kind=e.target.value;render();};
 const answer=$('#answer');if(answer){answer.oninput=()=>{rememberDraft();updateLines();updateHints();};answer.onscroll=updateLines;answer.onkeydown=e=>{if(answer.classList.contains('code-editor')&&e.altKey&&!e.ctrlKey&&!e.metaKey&&(e.code==='Minus'||['-','–','−'].includes(e.key))){e.preventDefault();const start=answer.selectionStart,end=answer.selectionEnd;answer.setRangeText('<-',start,end,'end');rememberDraft();updateLines();updateHints();return;}if(answer.classList.contains('code-editor')&&e.shiftKey&&(e.ctrlKey||e.metaKey)&&e.code==='KeyM'){e.preventDefault();const start=answer.selectionStart,end=answer.selectionEnd;answer.setRangeText(' |> ',start,end,'end');rememberDraft();updateLines();updateHints();return;}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();evaluate(true);}if(e.key==='Tab'&&answer.classList.contains('code-editor')){e.preventDefault();const start=answer.selectionStart,end=answer.selectionEnd;answer.setRangeText('  ',start,end,'end');rememberDraft();updateLines();}};queueMicrotask(updateLines);}
 document.querySelectorAll('input[name="choice"]').forEach(r=>r.onchange=()=>{session.choice=+r.value;progress.drafts[currentDraftKey()]=r.value;save();});
 if($('#report-description'))$('#report-description').oninput=e=>session.reportDraft=e.target.value;
 if($('#report-form'))$('#report-form').onsubmit=e=>{e.preventDefault();submitReport();};
 if($('#import'))$('#import').onchange=importBackup;
}
function act(action,id){switch(action){case 'open':openExercise(id);break;case 'variant':openExercise(null,makeVariant(Date.now()));break;case 'next':{const pool=current.olaYear?exercises.filter(x=>x.olaYear===current.olaYear):coreActiveExercises();const i=pool.findIndex(x=>x.id===current.id);openExercise(pool[(i+1)%pool.length].id);break;}case 'preview-data':previewData();break;case 'skip':skipCurrent();break;case 'report':if(current&&!busy){rememberDraft();session.reportOpen=true;render();$('#report-description')?.focus();}break;case 'cancel-report':session.reportOpen=false;render();break;case 'refresh-reports':sharedReports.refresh(progress.reports);break;case 'report-status':{const report=sharedReports.reports.find(r=>r.id===id)||progress.reports.find(r=>r.id===id);if(report)sharedReports.status(id,report.status==='open'?'resolved':'open').catch(error=>toast(error.message));break;}case 'hint':rememberDraft();session.hinted=true;render();break;case 'solution':rememberDraft();session.revealed=true;progress.revealedDrafts??={};progress.revealedDrafts[currentDraftKey()]=true;save();render();break;case 'run':evaluate(false);break;case 'submit':evaluate(true);break;case 'reset-code':if(current){progress.drafts[currentDraftKey()]=current.starter||'';save();$('#answer').value=current.starter||'';updateLines();updateHints();}break;case 'restart':runSequence++;resetEngine();setBusy(false);runtimeStatus='R genstarter ved næste kørsel';if($('#runtime-status'))$('#runtime-status').textContent=runtimeStatus;toast('R-motoren er nulstillet. Din kode er bevaret.');break;case 'start-exam':startExam();break;case 'resume-exam':resumeExam();break;case 'finish-exam':if(confirm('Afslut prøven nu? Opgaver, du vælger at springe over, tæller ikke med i scoren. Andre ubesvarede opgaver tæller som forkerte.'))finishExam();break;case 'export':exportBackup();break;case 'clear-data':if(confirm(account.user?'Nulstil alle resultater på din konto, også online? Eksportér en backup først.':'Vil du slette alle dine lokale resultater og kladder?')){progress=emptyProgress();save();render();toast('Dine data er nulstillet. Ændringen gemmes med din normale gemmemetode.');}break;}}
function exportBackup(){rememberDraft();const blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`r-lab-backup-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Din backup er klar til download.');}
async function importBackup(e){const file=e.target.files[0];if(!file)return;try{if(file.size>20_000_000)throw Error('Filen er for stor (maks. 20 MB).');const imported=validateProgress(JSON.parse(await file.text()));if(confirm(`Erstat dine nuværende data${account.user?' (også online)':''} med ${imported.attempts.length} forsøg fra backupfilen?`)){progress=imported;save();render();toast('Din backup er indlæst.');}}catch(err){toast(err.message||'Backup kunne ikke læses.');}}
setInterval(()=>{if(current&&document.visibilityState==='visible'&&!busy)session.seconds++;if(progress.activeExam){if(Date.now()>=progress.activeExam.endsAt)finishExam();else if($('#exam-timer'))$('#exam-timer').textContent=examTime();}},1000);
window.addEventListener('beforeunload',rememberDraft);
account=new Account({storage,getProgress:()=>progress,setProgress:p=>{progress=p;},render,toast,beforeSwitch:()=>{rememberDraft();runSequence++;current=null;session=null;examMode=false;busy=false;}});
render();
account.init().finally(()=>sharedReports.refresh(progress.reports));
setInterval(()=>{if(page==='reports'&&!current)sharedReports.refresh(progress.reports);},30000);
window.addEventListener('online',()=>sharedReports.refresh(progress.reports));
